 "content": "from collections import deque

def transform(grid):
    """Fill zero-valued regions enclosed by color-1 outlines with color 3;
    add color-2 one-cell exterior halo around each such enclosure.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            region = []
            boundary = set()
            exterior = False
            while q:
                y, x = q.popleft()
                region.append((y, x))
                if y in (0, h-1) or x in (0, w-1):
                    exterior = True
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if not (0 <= yy < h and 0 <= xx < w):
                        exterior = True
                    elif grid[yy][xx] == 1:
                        boundary.add((yy, xx))
                    elif grid[yy][xx] == 0 and (yy, xx) not in seen:
                        seen.add((yy, xx)); q.append((yy, xx))
            if not exterior and boundary:
                for y, x in region:
                    out[y][x] = 3
                # Halo is applied around the full boundary, excluding original ink.
                for y, x in boundary:
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        yy, xx = y+dy, x+dx
                        if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0 and (yy,xx) not in region:
                            out[yy][xx] = 2
    return out
"
